app.use(async (req, res, next) => {              // mounted before all routes
  try {
    const grant = await policy.lookup(req);      // explicit grant source
    if (!grant) return res.sendStatus(403);      // no grant -> deny
    req.grant = grant;
    next();
  } catch (err) {
    res.sendStatus(503);                         // fail closed, never next()
  }
});
